/**
 * Inline SVG icon set. We deliberately do NOT use emojis (which look amateurish
 * and render inconsistently across platforms) or icon fonts (which require
 * loading an external file). All icons are minimal Lucide-compatible SVGs
 * rendered inline with currentColor stroke so they inherit text color.
 */
if ( ! defined( 'ABSPATH' ) ) exit;

class CMMS_Icons {

    public static function get( $name, $size = 18 ) {
        $paths = self::library();
        if ( ! isset( $paths[ $name ] ) ) return '';
        $size = (int) $size;
        $body = $paths[ $name ];
        return '<svg xmlns="http://www.w3.org/2000/svg" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $body . '</svg>';
    }

    public static function e( $name, $size = 18 ) {
        echo self::get( $name, $size ); // Pre-built SVG strings - safe.
    }

