    /** Map an asset_type slug to an icon. */
    public static function for_asset_type( $type ) {
        $map = array(
            'machine'   => 'tool',
            'equipment' => 'box',
            'location'  => 'map-pin',
            'vehicle'   => 'truck',
            'other'     => 'box',
        );
        return $map[ $type ] ?? 'box';
    }
